using System.IO;using System.Text.Json;using SaarOSS.Rechnungsprogramm.Models;
namespace SaarOSS.Rechnungsprogramm.Services;
public sealed class EInvoiceCustomerSettingsService
{
 static readonly JsonSerializerOptions Options=new(){WriteIndented=true};readonly string _folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"SaarOSS","Rechnungsprogramm");string FileName=>Path.Combine(_folder,"e-invoice-customers.json");string Backup=>Path.Combine(_folder,"e-invoice-customers.backup.json");
 public EInvoiceCustomerSettingsStore Load(){if(!File.Exists(FileName))return new();try{return JsonSerializer.Deserialize<EInvoiceCustomerSettingsStore>(File.ReadAllText(FileName),Options)??new();}catch(Exception ex){throw new InvalidDataException("Die E-Rechnungs-Kundendaten konnten nicht gelesen werden und wurden nicht überschrieben.",ex);}}
 public EInvoiceCustomerSettings GetOrCreate(EInvoiceCustomerSettingsStore store,Guid id){var x=store.Customers.FirstOrDefault(v=>v.CustomerId==id);if(x is not null)return x;x=new(){CustomerId=id};store.Customers.Add(x);return x;}
 public void Save(EInvoiceCustomerSettingsStore store,EInvoiceCustomerSettings value){Validate(value);value.UpdatedAt=DateTimeOffset.Now;var i=store.Customers.FindIndex(x=>x.CustomerId==value.CustomerId);if(i>=0)store.Customers[i]=value;else store.Customers.Add(value);Directory.CreateDirectory(_folder);var temp=FileName+".tmp";File.WriteAllText(temp,JsonSerializer.Serialize(store,Options));if(File.Exists(FileName))File.Copy(FileName,Backup,true);File.Move(temp,FileName,true);}
 static void Validate(EInvoiceCustomerSettings x){var types=new[]{"Privatkunde","Unternehmen","Öffentliche Verwaltung"};var formats=new[]{"PDF","XRechnung","ZUGFeRD (später)"};if(!types.Contains(x.CustomerType))throw new ArgumentException("Ungültiger Kundentyp.");if(!formats.Contains(x.InvoiceFormat))throw new ArgumentException("Ungültiges Rechnungsformat.");if(!string.IsNullOrWhiteSpace(x.EInvoiceEmail)&&!x.EInvoiceEmail.Contains('@'))throw new ArgumentException("Bitte eine gültige E-Rechnungs-E-Mail eingeben.");if(x.CustomerType=="Öffentliche Verwaltung"&&x.InvoiceFormat=="XRechnung"&&string.IsNullOrWhiteSpace(x.RoutingId))throw new ArgumentException("Für eine öffentliche Verwaltung mit XRechnung ist eine Leitweg-ID erforderlich.");}
}
